'use strict';

function normalizeToken(token) {
  if (typeof token !== 'string') {
    throw new TypeError('token must be a string');
  }
  const normalized = token.trim().toLowerCase();
  if (normalized.length === 0) {
    throw new TypeError('token must not be empty');
  }
  return normalized;
}

function createPermitRegistry(initialTokens) {
  if (!Array.isArray(initialTokens)) {
    throw new TypeError('initialTokens must be an array');
  }

  const normalized = initialTokens.map(normalizeToken);
  const tokens = new Set(normalized);

  return {
    add(token) {
      const value = normalizeToken(token);
      if (tokens.has(value)) return false;
      tokens.add(value);
      return true;
    },
    has(token) {
      return tokens.has(normalizeToken(token));
    },
    remove(token) {
      const value = normalizeToken(token);
      return tokens.has(value);
    },
    list() {
      return Array.from(tokens).sort();
    }
  };
}

module.exports = { createPermitRegistry };

