'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api).sort(), ['createPermitRegistry']);
const { createPermitRegistry } = api;

for (const value of [null, {}, 'token']) {
  assert.throws(() => createPermitRegistry(value), TypeError);
}
for (const tokens of [[1], [''], ['   '], [new String('x')]]) {
  assert.throws(() => createPermitRegistry(tokens), TypeError);
}

const initial = [' Beta ', 'alpha', 'ALPHA', 'z'];
const original = initial.slice();
const registry = createPermitRegistry(initial);
assert.deepStrictEqual(initial, original);
assert.deepStrictEqual(registry.list(), ['alpha', 'beta', 'z']);

initial[0] = 'changed';
initial.push('new');
assert.deepStrictEqual(registry.list(), ['alpha', 'beta', 'z']);
assert.equal(registry.has(' BETA '), true);
assert.equal(registry.has('missing'), false);
assert.equal(registry.add(' Gamma '), true);
assert.equal(registry.add('gAmMa'), false);
assert.deepStrictEqual(registry.list(), ['alpha', 'beta', 'gamma', 'z']);
assert.equal(registry.remove(' BETA'), true);
assert.equal(registry.remove('beta'), false);
assert.equal(registry.has('beta'), false);

const exposed = registry.list();
exposed.length = 0;
assert.deepStrictEqual(registry.list(), ['alpha', 'gamma', 'z']);
assert.notStrictEqual(registry.list(), registry.list());

const stable = registry.list();
for (const operation of [
  () => registry.add(' '),
  () => registry.has(7),
  () => registry.remove(null)
]) {
  assert.throws(operation, TypeError);
  assert.deepStrictEqual(registry.list(), stable);
}

const empty = createPermitRegistry([]);
assert.deepStrictEqual(empty.list(), []);
assert.equal(empty.add('solo'), true);
assert.deepStrictEqual(empty.list(), ['solo']);
assert.equal(registry.has('solo'), false);

